\documentclass[10pt,letterpaper]{article}

% =====================================================================
% PART 1: APPEARANCE -- page, font, colors, and spacing
% =====================================================================

\usepackage[
  letterpaper,
  left=25bp,
  right=29bp,
  top=25bp,
  bottom=25bp,
  noheadfoot
]{geometry}

\usepackage[T1]{fontenc}
\usepackage[utf8]{inputenc}
\usepackage[type1,lining,proportional]{roboto-serif}
\usepackage{xcolor}
\usepackage{graphicx}
\usepackage{enumitem}
