\usepackage[normalem]{ulem}
\usepackage{hyperref}

\definecolor{LinkBlue}{RGB}{17,85,204}
\definecolor{RuleGray}{RGB}{170,183,196}

\hypersetup{
  colorlinks=true,
  urlcolor=LinkBlue,
  linkcolor=LinkBlue,
  pdftitle={Kirtan Thummar - Resume},
  pdfauthor={Kirtan Thummar}
}

% Make text in the PDF searchable and copyable.
\input{glyphtounicode}
\pdfgentounicode=1

\pagestyle{empty}
\setlength{\parindent}{0pt}
\setlength{\parskip}{0pt}
\setlength{\tabcolsep}{0pt}

% Font weights from the original: extra-light body, regular subheadings,
% and medium-weight name / section headings.
\renewcommand{\seriesdefault}{el}
\newcommand{\ResumeEmphasis}[1]{{\fontseries{m}\selectfont #1}}
\newcommand{\ResumeHeading}[1]{{\fontseries{medium}\selectfont #1}}

% All spacing settings live here, rather than beside individual lines.
\newcommand{\BodyFont}{\fontsize{8bp}{14.65bp}\selectfont}
\newcommand{\SectionFont}{\fontsize{10bp}{12bp}\selectfont}
\newcommand{\NameFont}{\fontsize{16.5bp}{20bp}\selectfont}
\newcommand{\ContactFont}{\fontsize{8.5bp}{12bp}\selectfont}
\newcommand{\ContactLinkFont}{\fontsize{8bp}{12bp}\fontseries{m}\selectfont}
\newcommand{\SubheadingFont}{\fontsize{8bp}{14.65bp}\fontseries{m}\selectfont}
\newcommand{\SkillFont}{\fontsize{8bp}{14.2bp}\selectfont}
\newcommand{\BulletFont}{\fontsize{7bp}{7bp}\fontseries{el}\selectfont}
\newlength{\SectionGap}
\newlength{\EntryGap}
\newlength{\SectionRuleThickness}
\setlength{\SectionGap}{15bp}
\setlength{\EntryGap}{4bp}
\setlength{\SectionRuleThickness}{1bp}
\renewcommand{\ULthickness}{1bp}
\setlength{\ULdepth}{1.1bp}

% The same round bullet as the original: 7bp font, scaled by 1.55.
\newcommand{\ResumeBullet}{%
  {\BulletFont\kern-1.75bp%
   \raisebox{0bp}[0pt][0pt]{\scalebox{1.55}{\textbullet}}}%
}

% Each bullet is a normal list item. Wrapped lines align with the text.
\newlist{ResumeBullets}{itemize}{1}
\setlist[ResumeBullets]{
  label=\ResumeBullet,
  leftmargin=8bp,
  labelwidth=4bp,
  labelsep=4bp,
  itemindent=0pt,
  topsep=0pt,
  partopsep=0pt,
  parsep=0pt,
  itemsep=0pt
}

% =====================================================================
% PART 2: REUSABLE COMMANDS -- define the layout once
% =====================================================================

% A real clickable link, with an underline that follows the text width.
\newcommand{\ResumeLink}[2]{\href{#1}{\uline{#2}}}

% Usage: \ResumeSection{EDUCATION}
\newcommand{\ResumeSection}[1]{%
  \par\addvspace{\SectionGap}%
  {\SectionFont\ResumeHeading{#1}\par}%
  \nobreak\vspace{1bp}%
  {\color{RuleGray}\hrule height \SectionRuleThickness}%
  \nobreak\vspace{2bp}%
}

% Usage: \ResumeEntry{Role - Organization}{Dates}
% The title wraps automatically; dates stay in the right-hand column.
\newcommand{\ResumeEntry}[2]{%
  \par\addvspace{\EntryGap}%
  \noindent\begin{tabularx}{\linewidth}{@{}X r@{}}%
    {\SubheadingFont #1} & {\SubheadingFont #2} \\
  \end{tabularx}\par\nobreak
}

% Usage: \SkillRow{Languages}{TypeScript, JavaScript, Python}
\newcommand{\SkillRow}[2]{\ResumeEmphasis{#1} & #2 \\}

