\ResumeEmphasis{M.S., Information Technology - Arizona State University}
  | May 2026 | GPA 4.00/4.00\par
\ResumeEmphasis{B.E., Information Technology - Gujarat Technological University}
  | Apr 2023\par

\ResumeSection{TECHNICAL SKILLS}
{\SkillFont
\begin{tabularx}{\linewidth}{@{}p{72bp}X@{}}
  \SkillRow{Languages}{TypeScript, JavaScript, Python, HTML, CSS}
  \SkillRow{Frameworks}{React, Next.js, Node.js, Flask, Django, Tailwind CSS, Material UI}
  \SkillRow{AI \& LLMs}{Amazon Bedrock, OpenAI, Claude, Gemini, MCP, RAG, Fine tuning, LangGraph, LangChain, CrewAI}
  \SkillRow{Cloud \& DevOps}{AWS (EC2, S3, Lambda, RDS, ECS, KMS, SQS, IAM, VPC, API Gateway, CloudWatch), GCP, Docker, GitHub Actions, CI/CD}
  \SkillRow{Database}{PostgreSQL, MySQL, pgvector, MongoDB, Supabase, DynamoDB}
\end{tabularx}\par}

\ResumeSection{EXPERIENCE}

\ResumeEntry
  {Co-founder \& Software Engineer \textit{(Part-Time)} -
   \ResumeLink{https://www.paperlyft.com/}{Paperlyft}}
  {Feb 2026 - Present}
\begin{ResumeBullets}
  \item Built a production AI platform converting scanned PDFs into accessible documents while preserving content, layout, and geometry.
  \item Built multimodal AI workflows with a custom agent harness for page generation, validation, and repair.
  \item Integrated automated accessibility checks, visual quality review, and human feedback into the document conversion workflow.
  \item Developed AWS infrastructure with CDK, Lambda, ECS Fargate, SQS, S3, and DynamoDB for asynchronous document processing.
  \item Work with prospective customers to translate MVP feedback into product priorities and architecture decisions.
  \item Implemented model selection, token-level cost tracking, and queue controls to balance output quality, latency, and cost.
\end{ResumeBullets}

\ResumeEntry
  {Software Engineer Intern - ASU Learning Engineering Institute}
  {Jan 2026 - May 2026}
\begin{ResumeBullets}
  \item Researched ethical issues in educational software and identified gaps in existing review workflows which mostly focuses on technical bugs.
  \item Built Critical Code Reviewer, a GitHub Action that reviews PRs with an LLM and posts feedback directly on relevant code lines.
  \item Improved review quality through structured prompts, repository context, validation, and evaluation of useful versus noisy findings.
  \item Continue maintaining CCR after the internship; testing it on real repositories and discuss design tradeoffs with institute mentors.
  \item Built Claude Code skills and a context management system for local reviews that surface less obvious ans unknown ethical issues.
\end{ResumeBullets}

\ResumeEntry
  {Full Stack AI Engineer \textit{(Part-Time) - NMTSA / Opportunity Hack}}
  {Oct 2025 - Jun 2026}
\begin{ResumeBullets}
  \item Turned a hackathon prototype into a live platform for NMTSA using Next.js, Node.js, PostgreSQL, AWS, Stripe, and a custom CMS.
  \item Translated nonprofit leaders' and therapists' clinical and operational needs into product requirements.
  \item Built a custom CMS, integrated Stripe payments, and added AI-powered multilingual dynamic translation.
  \item Supported AWS deployment, CI/CD, testing, debugging, and production handoff as the product moved from prototype to daily use.
\end{ResumeBullets}

\ResumeEntry
  {Software Engineer - Braincuber Technologies}
  {Sep 2022 - Aug 2024}
\begin{ResumeBullets}
  \item Gathered requirements from clients and prospective customers for a "Rewards and Engagement platform" serving the UAE market.
  \item Collaborated with developers to migrate the platform from React to Next.js based on client requirements.
  \item Progressed from junior engineer to owning development of an AI healthcare initiative with Next.js, PostgreSQL, OpenAI, and AWS.
  \item Worked with doctors and patient consultation transcripts to develop AI-assisted analysis for the healthcare initiative.
  \item Managed staging and production AWS environments, deployments, testing, and debugging to support production releases.
\end{ResumeBullets}

\ResumeSection{PERSONAL PROJECT}
\ResumeEntry
  {Vctrx - Agentic AI \& Infrastructure Platform}
  {\ResumeHeading{Apr 2025 - Dec 2025}}
\begin{ResumeBullets}
  \item Built Vctrx, an agentic AI Coding harness where AI agents use role-based context, tools, memory, and human approval where needed.
  \item Integrated multiple LLM providers, RAG, PostgreSQL, and MCP-based tools into a shared agent infrastructure.
  \item Created central kanban panel for all roles and tasks to automate the whole CI/CD pipeline for the project development.
  \item Designed the platform in modular components so models, tools, and infrastructure can change as product needs evolve.
\end{ResumeBullets}

\ResumeSection{CREDENTIALS \& CERTIFICATIONS}
\ResumeEmphasis{AWS Certified Cloud Practitioner} - Oct 2025\par
\ResumeEmphasis{Recognition:}
  1st Place, ASU AI + Elections Hackathon (2026) |
  1st Place, Opportunity Hack (2025) |
  2nd Place, SunHacks (2025)\par

\end{document}

